function PolymerNetwork() {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    let animationId;
    let crosslinks = [];
    let chains = [];
    let loops = [];
    let dangling = [];
    let isMobile = window.innerWidth < 768;
    let dpr = window.devicePixelRatio || 1;
    let lastBuildWidth = 0;
    let lastBuildHeight = 0;

    function resize() {
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.scale(dpr, dpr);
      const newIsMobile = window.innerWidth < 768;

      // Only rebuild the network if this is a "big" resize:
      //   - first time (no previous build)
      //   - mobile <-> desktop transition
      //   - width changed significantly (orientation change, real resize)
      // Ignore small height-only changes (mobile URL bar showing/hiding)
      const widthChange = Math.abs(rect.width - lastBuildWidth);
      const significantChange = lastBuildWidth === 0
        || newIsMobile !== isMobile
        || widthChange > 60;

      isMobile = newIsMobile;

      if (significantChange) {
        buildNetwork();
        lastBuildWidth = rect.width;
        lastBuildHeight = rect.height;
      } else {
        // Soft adjust: scale existing node base positions to fit new height
        // This keeps the same network configuration but adapts to new canvas size
        if (lastBuildHeight > 0 && rect.height !== lastBuildHeight) {
          const scaleY = rect.height / lastBuildHeight;
          crosslinks.forEach(c => {
            c.baseY *= scaleY;
            c.y *= scaleY;
          });
          lastBuildHeight = rect.height;
        }
      }
    }

    // Generate N internal control points for a chain (so chains are wavy and can entangle)
    // baseAmpFraction: amplitude as a fraction of chain length so longer chains curve more
    function makeWaveOffsets(n) {
      const arr = [];
      for (let i = 0; i < n; i++) {
        arr.push({
          phase: Math.random() * Math.PI * 2,
          speed: 0.004 + Math.random() * 0.008,
          // ampFraction: each wave point will use this fraction of the chain's actual length
          ampFraction: 0.10 + Math.random() * 0.10,
          sign: i % 2 === 0 ? 1 : -1,
        });
      }
      return arr;
    }

    function buildNetwork() {
      const rect = canvas.getBoundingClientRect();
      const W = rect.width;
      const H = rect.height;
      const nNodes = isMobile ? 11 : 20;
      crosslinks = [];
      chains = [];
      loops = [];
      dangling = [];

      // Step 1: create nodes with target functionality (mostly 4, some 3)
      for (let i = 0; i < nNodes; i++) {
        const targetFunc = Math.random() < 0.75 ? 4 : 3;
        crosslinks.push({
          x: Math.random() * W,
          y: Math.random() * H,
          baseX: 0, baseY: 0,
          phase: Math.random() * Math.PI * 2,
          targetFunc,
          slotsUsed: 0,
        });
      }
      crosslinks.forEach(c => { c.baseX = c.x; c.baseY = c.y; });

      // Step 2: RESERVE slots for loops FIRST (before any inter-node connections).
      // This guarantees loops actually appear in the topology.
      const loopCount = isMobile ? 2 : 3;
      const loopNodes = [...Array(nNodes).keys()]
        .sort(() => Math.random() - 0.5)
        .slice(0, loopCount);

      loopNodes.forEach(i => {
        const node = crosslinks[i];
        if (node.targetFunc - node.slotsUsed >= 2) {
          loops.push({
            node: i,
            angle: Math.random() * Math.PI * 2,
            size: 55 + Math.random() * 35,
            aspect: 0.45 + Math.random() * 0.4,
            phase: Math.random() * Math.PI * 2,
            phaseSpeed: 0.003 + Math.random() * 0.005,
          });
          node.slotsUsed += 2;
        }
      });

      // Step 3: RESERVE slots for dangling chain ends (chain-end defects).
      // We pick a set of nodes and reserve 1 slot on each.
      const danglingCount = isMobile ? 5 : 8;
      const danglingNodes = [];
      const candidates = [...Array(nNodes).keys()]
        .filter(i => crosslinks[i].slotsUsed < crosslinks[i].targetFunc)
        .sort(() => Math.random() - 0.5);

      for (let k = 0; k < Math.min(danglingCount, candidates.length); k++) {
        const i = candidates[k];
        const node = crosslinks[i];
        if (node.slotsUsed >= node.targetFunc) continue;
        danglingNodes.push(i);
        // We don't push to dangling[] yet; we'll do it AFTER deciding chain connections,
        // because we want danglings drawn last (on top, drifting freely).
        node.slotsUsed++; // reserve the slot
      }

      // Step 4: connect remaining slots to nearest neighbors with available slots.
      // Process in random order to avoid bias.
      const order = [...Array(nNodes).keys()].sort(() => Math.random() - 0.5);
      const alreadyConnected = (i, j) =>
        chains.some(c => (c.a === i && c.b === j) || (c.a === j && c.b === i));

      for (const i of order) {
        const a = crosslinks[i];
        const neighbors = crosslinks
          .map((b, j) => ({ j, d: i === j ? Infinity : Math.hypot(a.x - b.x, a.y - b.y) }))
          .sort((x, y) => x.d - y.d);

        for (const { j } of neighbors) {
          if (a.slotsUsed >= a.targetFunc) break;
          const b = crosslinks[j];
          if (b.slotsUsed >= b.targetFunc) continue;
          if (alreadyConnected(i, j)) continue;
          chains.push({ a: i, b: j, waves: makeWaveOffsets(3) });
          a.slotsUsed++;
          b.slotsUsed++;
        }
      }

      // Step 5: now actually instantiate the dangling chains
      // (orient them away from the densest crowd of neighbors, so they appear to drift outward)
      danglingNodes.forEach(i => {
        const node = crosslinks[i];
        // average direction TO neighbors -> opposite is a good outward direction
        let sumX = 0, sumY = 0, count = 0;
        chains.forEach(c => {
          if (c.a === i) {
            const o = crosslinks[c.b];
            sumX += o.x - node.x; sumY += o.y - node.y; count++;
          } else if (c.b === i) {
            const o = crosslinks[c.a];
            sumX += o.x - node.x; sumY += o.y - node.y; count++;
          }
        });
        let outAngle;
        if (count > 0) {
          // point dangling chain in the OPPOSITE direction of average neighbor direction
          outAngle = Math.atan2(-sumY, -sumX) + (Math.random() - 0.5) * 0.8;
        } else {
          outAngle = Math.random() * Math.PI * 2;
        }
        dangling.push({
          node: i,
          angle: outAngle,
          length: 75 + Math.random() * 55,
          tipPhase: Math.random() * Math.PI * 2,
          tipSpeed: 0.006 + Math.random() * 0.008,
          waves: makeWaveOffsets(4),
        });
      });
    }

    // Draw a wavy chain from point P0 to point P1 with N internal wave-controlled points
    function drawWavyChain(p0x, p0y, p1x, p1y, waves) {
      const dx = p1x - p0x;
      const dy = p1y - p0y;
      const len = Math.hypot(dx, dy);
      if (len < 1) return;
      const nx = -dy / len;
      const ny = dx / len;

      const N = waves.length;
      const pts = [{ x: p0x, y: p0y }];
      for (let i = 0; i < N; i++) {
        waves[i].phase += waves[i].speed;
        const t = (i + 1) / (N + 1);
        const lx = p0x + dx * t;
        const ly = p0y + dy * t;
        // amplitude scales with the chain's current length, so long chains are visibly wavy
        const amp = waves[i].ampFraction * len;
        const off = Math.sin(waves[i].phase) * amp * waves[i].sign;
        pts.push({ x: lx + nx * off, y: ly + ny * off });
      }
      pts.push({ x: p1x, y: p1y });

      ctx.beginPath();
      ctx.moveTo(pts[0].x, pts[0].y);
      for (let i = 1; i < pts.length - 1; i++) {
        const mx = (pts[i].x + pts[i + 1].x) / 2;
        const my = (pts[i].y + pts[i + 1].y) / 2;
        ctx.quadraticCurveTo(pts[i].x, pts[i].y, mx, my);
      }
      const last = pts[pts.length - 1];
      ctx.lineTo(last.x, last.y);
      ctx.stroke();
    }

    function animate() {
      const rect = canvas.getBoundingClientRect();
      const W = rect.width;
      const H = rect.height;
      ctx.clearRect(0, 0, W, H);

      // Drift crosslinks
      crosslinks.forEach(c => {
        c.phase += 0.003;
        c.x = c.baseX + Math.sin(c.phase) * 14 + Math.cos(c.phase * 0.7) * 8;
        c.y = c.baseY + Math.cos(c.phase * 0.9) * 14 + Math.sin(c.phase * 0.5) * 6;
      });

      ctx.lineWidth = 1;
      ctx.strokeStyle = "rgba(140, 120, 95, 0.22)";

      // Regular chains — wavy, multi-segment so they can visually entangle each other
      chains.forEach(ch => {
        const a = crosslinks[ch.a];
        const b = crosslinks[ch.b];
        drawWavyChain(a.x, a.y, b.x, b.y, ch.waves);
      });

      // Loops — chain that exits node, makes a smooth teardrop in space, returns to same node
      loops.forEach(lp => {
        lp.phase += lp.phaseSpeed;
        const node = crosslinks[lp.node];
        const ang = lp.angle + Math.sin(lp.phase) * 0.15;
        const breathe = 1 + Math.sin(lp.phase * 1.3) * 0.08;
        const size = lp.size * breathe;

        // Direction unit vectors: forward (along loop axis) and side (perpendicular)
        const fx = Math.cos(ang);
        const fy = Math.sin(ang);
        const sx = -fy;
        const sy = fx;

        // The loop is a teardrop: starts at node, swings out to one side, curves around
        // the far point smoothly, and comes back from the other side.
        // The far tip is along the forward direction.
        const tipX = node.x + fx * size * 1.4;
        const tipY = node.y + fy * size * 1.4;

        // Width of the loop (how far it bulges sideways)
        const width = size * lp.aspect;

        // For the far tip to be SMOOTH (no point), the tangent of the curve at the tip
        // must be perpendicular to the loop axis. We do this by placing the bezier
        // control points NEAR the tip on opposite sides along the perpendicular axis.
        // Outgoing curve: node -> tip, with control points pulling toward +side then -side at tip
        const out_c1x = node.x + fx * size * 0.3 + sx * width;
        const out_c1y = node.y + fy * size * 0.3 + sy * width;
        const out_c2x = tipX + sx * width * 0.7;
        const out_c2y = tipY + sy * width * 0.7;

        // Returning curve: tip -> node, mirrored (opposite side)
        const ret_c1x = tipX - sx * width * 0.7;
        const ret_c1y = tipY - sy * width * 0.7;
        const ret_c2x = node.x + fx * size * 0.3 - sx * width;
        const ret_c2y = node.y + fy * size * 0.3 - sy * width;

        ctx.beginPath();
        ctx.moveTo(node.x, node.y);
        ctx.bezierCurveTo(out_c1x, out_c1y, out_c2x, out_c2y, tipX, tipY);
        ctx.bezierCurveTo(ret_c1x, ret_c1y, ret_c2x, ret_c2y, node.x, node.y);
        ctx.stroke();
      });

      // Dangling chains — long flowing tendrils with drifting free tips
      dangling.forEach(d => {
        d.tipPhase += d.tipSpeed;
        const node = crosslinks[d.node];
        const driftX = Math.sin(d.tipPhase) * 14 + Math.cos(d.tipPhase * 0.6) * 8;
        const driftY = Math.cos(d.tipPhase * 0.8) * 14 + Math.sin(d.tipPhase * 0.4) * 8;
        const tipX = node.x + Math.cos(d.angle) * d.length + driftX;
        const tipY = node.y + Math.sin(d.angle) * d.length + driftY;
        drawWavyChain(node.x, node.y, tipX, tipY, d.waves);
      });

      // Crosslink nodes (drawn last so they sit on top)
      crosslinks.forEach(c => {
        const grad = ctx.createRadialGradient(c.x, c.y, 0, c.x, c.y, 12);
        grad.addColorStop(0, "rgba(120, 95, 70, 0.25)");
        grad.addColorStop(1, "rgba(120, 95, 70, 0)");
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(c.x, c.y, 12, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = "rgba(90, 70, 50, 0.5)";
        ctx.beginPath();
        ctx.arc(c.x, c.y, 2.5, 0, Math.PI * 2);
        ctx.fill();
      });

      animationId = requestAnimationFrame(animate);
    }

    resize();
    window.addEventListener("resize", resize);
    animate();

    return () => {
      cancelAnimationFrame(animationId);
      window.removeEventListener("resize", resize);
    };
  }, []);

  return (
    <canvas
      ref={canvasRef}
      style={{
        position: "absolute",
        top: 0, left: 0, width: "100%", height: "100%",
        pointerEvents: "none",
        zIndex: 0,
      }}
      aria-hidden="true"
    />
  );
}

// ============ NEWS PAGES ============

function NewsListPage({ onNavigate, onOpenNews }) {
  return (
    <div style={{ background: "#FCFAF7", minHeight: "100vh", color: "#1a1a1a" }}>
      <section style={{ maxWidth: 900, margin: "0 auto", padding: "140px 32px 80px" }}>
        <Reveal>
          <div style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 11, letterSpacing: "0.14em", textTransform: "uppercase", color: "#aaa", marginBottom: 24, fontWeight: 500 }}>News</div>
        </Reveal>
        <Reveal delay={0.05}>
          <h1 style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "clamp(36px, 6vw, 64px)", fontWeight: 300, lineHeight: 1.1, letterSpacing: "-0.03em", marginBottom: 24 }}>
            Latest <span style={{ fontWeight: 600, fontStyle: "italic" }}>news</span>
          </h1>
        </Reveal>
        <Reveal delay={0.1}>
          <p style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 15, color: "#888", lineHeight: 1.7, fontWeight: 300, maxWidth: 600, marginBottom: 60 }}>
            Updates on publications, grants, talks, awards, and the next steps in my professional journey.
          </p>
        </Reveal>

        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {NEWS.map((n, i) => (
            <Reveal key={n.slug} delay={0.05 * i}>
              <article onClick={() => onOpenNews(n.slug)} style={{ cursor: "pointer", padding: "32px 24px", borderRadius: 8, transition: "background 0.3s", display: "grid", gridTemplateColumns: n.image ? "140px 1fr" : "1fr", gap: 24, alignItems: "start" }}
                onMouseEnter={e => e.currentTarget.style.background = "rgba(0,0,0,0.02)"}
                onMouseLeave={e => e.currentTarget.style.background = "transparent"}
                className="news-card">
                {n.image && (
                  <div style={{ width: "100%", aspectRatio: "1/1", borderRadius: 6, overflow: "hidden", background: "#eae3d6" }}>
                    <img src={n.image} alt={n.title} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                  </div>
                )}
                <div>
                  <div style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 12, color: "#aaa", letterSpacing: "0.04em", marginBottom: 8 }}>{formatDate(n.date)}</div>
                  <h2 style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 24, fontWeight: 600, lineHeight: 1.3, marginBottom: 10, letterSpacing: "-0.01em" }}>{n.title}</h2>
                  <p style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 14, color: "#666", lineHeight: 1.7, fontWeight: 300, marginBottom: 12 }}>{n.excerpt}</p>
                  <span style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 12, letterSpacing: "0.06em", textTransform: "uppercase", color: "#1a1a1a", borderBottom: "1px solid #1a1a1a", paddingBottom: 2, fontWeight: 500 }}>Read more {"\u2192"}</span>
                </div>
              </article>
            </Reveal>
          ))}
        </div>

        <div style={{ marginTop: 64 }}>
          <span onClick={() => onNavigate("hero")} style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 13, letterSpacing: "0.06em", textTransform: "uppercase", color: "#888", cursor: "pointer" }}>{"\u2190"} Back to home</span>
        </div>
      </section>

      <style>{`@media(max-width:640px){.news-card{grid-template-columns:1fr !important;}}`}</style>
    </div>
  );
}

function NewsArticlePage({ slug, onNavigate, onOpenNews }) {
  const item = NEWS.find(n => n.slug === slug);
  if (!item) {
    return (
      <div style={{ background: "#FCFAF7", minHeight: "100vh", padding: "140px 32px", textAlign: "center" }}>
        <h1 style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 32, marginBottom: 16 }}>Article not found</h1>
        <span onClick={() => onNavigate("news")} style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 13, color: "#1a1a1a", textDecoration: "underline", cursor: "pointer" }}>Back to news</span>
      </div>
    );
  }

  // Find next/prev for navigation
  const idx = NEWS.findIndex(n => n.slug === slug);
  const newer = idx > 0 ? NEWS[idx - 1] : null;
  const older = idx < NEWS.length - 1 ? NEWS[idx + 1] : null;

  return (
    <div style={{ background: "#FCFAF7", minHeight: "100vh", color: "#1a1a1a" }}>
      <article style={{ maxWidth: 720, margin: "0 auto", padding: "140px 32px 80px" }}>
        <Reveal>
          <span onClick={() => onNavigate("news")} style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 12, letterSpacing: "0.06em", textTransform: "uppercase", color: "#aaa", cursor: "pointer", display: "inline-block", marginBottom: 32 }}>{"\u2190"} All news</span>
        </Reveal>
        <Reveal delay={0.05}>
          <div style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 13, color: "#aaa", letterSpacing: "0.04em", marginBottom: 16 }}>{formatDate(item.date)}</div>
        </Reveal>
        <Reveal delay={0.1}>
          <h1 style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "clamp(32px, 5vw, 48px)", fontWeight: 600, lineHeight: 1.2, letterSpacing: "-0.02em", marginBottom: 32 }}>{item.title}</h1>
        </Reveal>
        {item.image && (
          <Reveal delay={0.15}>
            <div style={{ width: "100%", borderRadius: 8, overflow: "hidden", marginBottom: 40, background: "#eae3d6" }}>
              <img src={item.image} alt={item.title} style={{ width: "100%", display: "block" }} />
            </div>
          </Reveal>
        )}
        <Reveal delay={0.2}>
          <div style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 16, color: "#444", lineHeight: 1.85, fontWeight: 300 }}>
            {item.content.split("\n").filter(Boolean).map((para, i) => (
              <p key={i} style={{ marginBottom: 20 }}>{para}</p>
            ))}
          </div>
        </Reveal>

        {/* Prev / Next navigation */}
        {(newer || older) && (
          <div style={{ marginTop: 80, paddingTop: 32, borderTop: "1px solid rgba(0,0,0,0.08)", display: "flex", justifyContent: "space-between", gap: 24, flexWrap: "wrap" }}>
            {older ? (
              <span onClick={() => onOpenNews(older.slug)} style={{ cursor: "pointer", maxWidth: "45%" }}>
                <div style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 11, color: "#aaa", letterSpacing: "0.06em", textTransform: "uppercase", marginBottom: 6 }}>{"\u2190"} Older</div>
                <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 16, fontWeight: 600, color: "#1a1a1a" }}>{older.title}</div>
              </span>
            ) : <span />}
            {newer ? (
              <span onClick={() => onOpenNews(newer.slug)} style={{ cursor: "pointer", maxWidth: "45%", textAlign: "right" }}>
                <div style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 11, color: "#aaa", letterSpacing: "0.06em", textTransform: "uppercase", marginBottom: 6 }}>Newer {"\u2192"}</div>
                <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 16, fontWeight: 600, color: "#1a1a1a" }}>{newer.title}</div>
              </span>
            ) : <span />}
          </div>
        )}
      </article>
    </div>
  );
}

function formatDate(iso) {
  const d = new Date(iso);
  return d.toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" });
}

// ============ MAIN APP WITH ROUTING ============
export default function App() {
  const [route, setRoute] = useState(() => parseHash());

  function parseHash() {
    const hash = window.location.hash.slice(1) || "/";
    if (hash.startsWith("/news/")) return { page: "article", slug: hash.slice(6) };
    if (hash === "/news") return { page: "news" };
    return { page: "home", section: hash.slice(1) || "hero" };
  }

  useEffect(() => {
    const handler = () => {
      const r = parseHash();
      setRoute(r);
      // Scroll to top when changing pages
      if (r.page !== "home") {
        window.scrollTo(0, 0);
      }
    };
    window.addEventListener("hashchange", handler);
    return () => window.removeEventListener("hashchange", handler);
  }, []);

  // Handle initial load with section anchor
  useEffect(() => {
    if (route.page === "home" && route.section && route.section !== "hero") {
      // Defer to allow render
      setTimeout(() => {
        document.getElementById(route.section)?.scrollIntoView({ behavior: "smooth", block: "start" });
      }, 100);
    }
  }, []);

  const navigate = (target) => {
    if (target === "news") {
      window.location.hash = "/news";
    } else if (target === "hero") {
      if (route.page !== "home") {
        window.location.hash = "/";
      } else {
        window.scrollTo({ top: 0, behavior: "smooth" });
      }
    } else {
      // It's a section on the home page
      if (route.page !== "home") {
        window.location.hash = "/" + target;
      } else {
        document.getElementById(target)?.scrollIntoView({ behavior: "smooth", block: "start" });
      }
    }
  };

  const openNews = (slug) => {
    window.location.hash = "/news/" + slug;
  };

  const globalStyles = (
    <style>{`
      @import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;0,500;0,600;0,700;1,400;1,500&family=DM+Sans:ital,wght@0,300;0,400;0,500;0,600;1,400&display=swap');
      *,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
      html{scroll-behavior:smooth;scroll-padding-top:80px}
      ::selection{background:#e8e0d4}
      .nav-hamburger{display:none!important}
      @media(max-width:640px){.nav-links-desktop{display:none!important}.nav-hamburger{display:block!important}}
      .social-link{display:inline-flex;align-items:center;justify-content:center;width:38px;height:38px;border-radius:50%;border:1px solid rgba(0,0,0,0.12);color:#888;text-decoration:none;font-size:14px;background:#FCFAF7;transition:all 0.3s}
      .social-link:hover{border-color:#1a1a1a;color:#1a1a1a;transform:translateY(-2px)}
      @media(max-width:768px){.about-grid{grid-template-columns:1fr!important;gap:40px!important}.research-head{font-size:28px!important}.edu-row{grid-template-columns:1fr!important}.chart-grid{grid-template-columns:1fr!important}}
      @keyframes bounce{0%,100%{transform:translateY(0)}50%{transform:translateY(6px)}}
      .carousel-scroll::-webkit-scrollbar{height:4px}.carousel-scroll::-webkit-scrollbar-thumb{background:#ddd;border-radius:4px}
    `}</style>
  );

  if (route.page === "news") {
    return (<>{globalStyles}<Nav active="news" onNavigate={navigate} /><NewsListPage onNavigate={navigate} onOpenNews={openNews} /></>);
  }
  if (route.page === "article") {
    return (<>{globalStyles}<Nav active="news" onNavigate={navigate} /><NewsArticlePage slug={route.slug} onNavigate={navigate} onOpenNews={openNews} /></>);
  }
  return <Portfolio onNavigate={navigate} onOpenNews={openNews} />;
}

